import 'package:dio/dio.dart';
import 'package:fynd/core/network/api_endpoints.dart';
import 'package:fynd/core/network/network_client.dart';

/// Generated By Abdullah Hameed

abstract class NotificationsRemoteDataSource {
  Future<Response> getAllNotifications();

  Future<Response> markAllAsRead();

  Future<Response> markAsRead({required int id});

  Future<Response> getUnreadCount();
}

class NotificationsRemoteDataSourceImpl
    implements NotificationsRemoteDataSource {
  @override
  Future<Response<dynamic>> getAllNotifications() {
    return NetworkClient.get(url: ApiEndpoints.notifications);
  }

  @override
  Future<Response<dynamic>> markAllAsRead() {
    return NetworkClient.patch(url: ApiEndpoints.markAllAsRead);
  }

  @override
  Future<Response<dynamic>> markAsRead({required int id}) {
    return NetworkClient.patch(url: ApiEndpoints.markAsRead(id: id));
  }

  @override
  Future<Response<dynamic>> getUnreadCount() {
    return NetworkClient.get(url: ApiEndpoints.unreadCount);
  }
}
